package com.superessence.cuttinx.core.resources

import com.superessence.cuttinx.core.audio.Biquad
import com.superessence.cuttinx.core.audio.Compressor
import com.superessence.cuttinx.core.audio.Limiter
import com.superessence.cuttinx.core.audio.Reverb
import kotlin.math.*

/**
 * Procedural sound design: every sound effect and music bed shipped with CUTTINX is generated by
 * this code. They are original works of SUPERESSENCE and free to use in any video (see LICENSES).
 */
object Synth {
    const val SR = 44100

    class Audio(val samples: FloatArray, val channels: Int, val sampleRate: Int = SR) {
        val durationUs get() = samples.size.toLong() / channels * 1_000_000 / sampleRate
    }

    data class Sfx(val id: String, val name: String, val category: String)
    data class Track(val id: String, val name: String, val mood: String, val bpm: Int, val seconds: Int)

    val sfxList = listOf(
        Sfx("whoosh", "Whoosh", "Transitions"), Sfx("riser", "Montée (riser)", "Transitions"), Sfx("swipe", "Glissement", "Transitions"),
        Sfx("impact", "Impact grave", "Impacts"), Sfx("boom", "Boom cinéma", "Impacts"), Sfx("punch", "Coup", "Impacts"),
        Sfx("pop", "Pop", "Interface"), Sfx("click", "Clic", "Interface"), Sfx("ding", "Ding", "Interface"), Sfx("success", "Succès", "Interface"),
        Sfx("error", "Erreur", "Interface"), Sfx("notify", "Notification", "Interface"), Sfx("type", "Frappe clavier", "Interface"),
        Sfx("shutter", "Déclencheur photo", "Objets"), Sfx("laser", "Laser", "Fun"), Sfx("glitch", "Glitch", "Fun"), Sfx("boing", "Boing", "Fun"),
        Sfx("heartbeat", "Battement de cœur", "Ambiance"), Sfx("wind", "Vent", "Ambiance"), Sfx("rain", "Pluie", "Ambiance"),
    )

    val musicList = listOf(
        Track("lofi", "Après-midi lo-fi", "Calme", 84, 64),
        Track("pop", "Énergie pop", "Dynamique", 120, 64),
        Track("ambient", "Aurore ambient", "Contemplatif", 70, 70),
        Track("epic", "Horizon épique", "Cinématique", 90, 64),
        Track("funk", "Groove funk", "Joyeux", 108, 60),
        Track("tech", "Pulsation tech", "Sport", 128, 60),
    )

    private fun noise(r: java.util.Random) = (r.nextFloat() * 2 - 1)

    fun sfx(id: String): Audio {
        val r = java.util.Random(id.hashCode().toLong())
        fun buf(sec: Double) = FloatArray((sec * SR).toInt())
        val out: FloatArray = when (id) {
            "whoosh", "swipe" -> {
                val len = if (id == "whoosh") 0.9 else 0.45
                val b = buf(len); val bp = Biquad(Biquad.Type.BANDPASS, 400.0, 1.2).also { it.configure(SR, 1) }
                for (i in b.indices) {
                    val t = i.toDouble() / b.size
                    if (i % 64 == 0) { bp.freq = 300 + 4000 * sin(PI * t).pow(2); bp.update() }
                    b[i] = (bp.processSample(noise(r).toDouble(), 0) * sin(PI * t).pow(1.5) * 2.2).toFloat()
                }
                b
            }
            "riser" -> {
                val b = buf(2.5)
                var ph = 0.0
                val hp = Biquad(Biquad.Type.HIGHPASS, 200.0).also { it.configure(SR, 1) }
                for (i in b.indices) {
                    val t = i.toDouble() / b.size
                    val f = 120 * 2.0.pow(t * 4)
                    ph += 2 * PI * f / SR
                    if (i % 64 == 0) { hp.freq = 200 + 6000 * t * t; hp.update() }
                    b[i] = ((sin(ph) * 0.35 + sin(ph * 1.01) * 0.25 + hp.processSample(noise(r).toDouble(), 0) * 0.6) * t.pow(1.6)).toFloat()
                }
                b
            }
            "impact", "boom", "punch" -> {
                val len = when (id) { "boom" -> 2.2; "punch" -> 0.35; else -> 1.2 }
                val b = buf(len); var ph = 0.0
                val lp = Biquad(Biquad.Type.LOWPASS, 2500.0).also { it.configure(SR, 1) }
                for (i in b.indices) {
                    val t = i.toDouble() / SR
                    val f = (if (id == "punch") 160.0 else 90.0) * exp(-t * 8) + 38
                    ph += 2 * PI * f / SR
                    val body = sin(ph) * exp(-t * (if (id == "boom") 2.0 else 5.0))
                    val crack = lp.processSample(noise(r).toDouble(), 0) * exp(-t * 30) * 0.8
                    b[i] = ((body + crack) * 0.9).toFloat()
                }
                if (id == "boom") reverbInPlace(b, 0.9, 0.35)
                b
            }
            "pop" -> { val b = buf(0.12); var ph = 0.0; for (i in b.indices) { val t = i.toDouble() / SR; ph += 2 * PI * (900 * exp(-t * 40) + 300) / SR; b[i] = (sin(ph) * exp(-t * 45)).toFloat() }; b }
            "click" -> { val b = buf(0.04); for (i in b.indices) { val t = i.toDouble() / SR; b[i] = ((sin(2 * PI * 3200 * t) * 0.5 + noise(r) * 0.5) * exp(-t * 250)).toFloat() }; b }
            "ding", "notify", "success" -> {
                val notes = when (id) { "ding" -> listOf(0.0 to 1318.5); "notify" -> listOf(0.0 to 987.8, 0.12 to 1318.5); else -> listOf(0.0 to 523.3, 0.1 to 659.3, 0.2 to 784.0, 0.3 to 1046.5) }
                val b = buf(1.4)
                for ((st, f) in notes) bell(b, st, f, 1.0)
                b
            }
            "error" -> { val b = buf(0.5); for (i in b.indices) { val t = i.toDouble() / SR; val f = if (t < 0.22) 220.0 else 180.0; b[i] = (sign(sin(2 * PI * f * t)) * 0.3 * (if (t % 0.25 < 0.2) 1 else 0) * exp(-t * 2)).toFloat() }; b }
            "type" -> {
                val b = buf(1.2)
                var t0 = 0.0
                while (t0 < 1.1) { val s = (t0 * SR).toInt(); for (k in 0 until 900) if (s + k < b.size) { val t = k.toDouble() / SR; b[s + k] += ((noise(r) * 0.6 + sin(2 * PI * 2000 * t) * 0.3) * exp(-t * 180)).toFloat() }; t0 += 0.09 + r.nextDouble() * 0.08 }
                b
            }
            "shutter" -> { val b = buf(0.3); for (i in b.indices) { val t = i.toDouble() / SR; val e = exp(-t * 60) + if (t > 0.09) exp(-(t - 0.09) * 70) * 0.8 else 0.0; b[i] = (noise(r) * e * 0.8).toFloat() }; b }
            "laser" -> { val b = buf(0.4); var ph = 0.0; for (i in b.indices) { val t = i.toDouble() / SR; ph += 2 * PI * (2400 * exp(-t * 9) + 200) / SR; b[i] = (sin(ph) * exp(-t * 6) * 0.7).toFloat() }; b }
            "glitch" -> {
                val b = buf(0.6)
                var i = 0
                while (i < b.size) { val len = 200 + r.nextInt(1800); val f = 100 + r.nextInt(3000); val sq = r.nextBoolean(); for (k in 0 until len) if (i + k < b.size) { val t = k.toDouble() / SR; b[i + k] = (if (sq) sign(sin(2 * PI * f * t)) * 0.3 else noise(r) * 0.4).toFloat() }; i += len + r.nextInt(600) }
                b
            }
            "boing" -> { val b = buf(0.7); var ph = 0.0; for (i in b.indices) { val t = i.toDouble() / SR; ph += 2 * PI * (220 + 180 * sin(2 * PI * 9 * t) * exp(-t * 4)) / SR; b[i] = (sin(ph) * exp(-t * 4.5) * 0.8).toFloat() }; b }
            "heartbeat" -> {
                val b = buf(2.0)
                for (beat in listOf(0.0, 0.25, 1.0, 1.25)) { val s = (beat * SR).toInt(); var ph = 0.0; for (k in 0 until (0.25 * SR).toInt()) if (s + k < b.size) { val t = k.toDouble() / SR; ph += 2 * PI * (60 * exp(-t * 10) + 40) / SR; b[s + k] += (sin(ph) * exp(-t * 18) * (if (beat % 1.0 == 0.0) 1.0 else 0.7)).toFloat() } }
                b
            }
            "wind", "rain" -> {
                val b = buf(8.0)
                val lp = Biquad(Biquad.Type.LOWPASS, if (id == "wind") 500.0 else 6000.0, 0.7).also { it.configure(SR, 1) }
                val hp = Biquad(Biquad.Type.HIGHPASS, if (id == "wind") 80.0 else 900.0).also { it.configure(SR, 1) }
                for (i in b.indices) {
                    val t = i.toDouble() / SR
                    if (id == "wind" && i % 128 == 0) { lp.freq = 350 + 300 * sin(t * 0.7) + 150 * sin(t * 1.9); lp.update() }
                    var v = hp.processSample(lp.processSample(noise(r).toDouble(), 0), 0)
                    if (id == "rain" && r.nextDouble() < 0.0008) v += noise(r) * 2
                    val fade = min(1.0, min(t, 8.0 - t) / 0.8)
                    b[i] = (v * fade * (if (id == "wind") 1.6 else 0.6)).toFloat()
                }
                b
            }
            else -> buf(0.1)
        }
        normalize(out, 0.89f)
        return Audio(out, 1)
    }

    private fun bell(b: FloatArray, startSec: Double, f: Double, amp: Double) {
        val s = (startSec * SR).toInt()
        for (k in 0 until b.size - s) {
            val t = k.toDouble() / SR
            val v = (sin(2 * PI * f * t) + 0.5 * sin(2 * PI * f * 2.76 * t) * exp(-t * 6) + 0.25 * sin(2 * PI * f * 5.4 * t) * exp(-t * 12)) * exp(-t * 3.5) * amp
            b[s + k] += (v * 0.4).toFloat()
        }
    }

    private fun reverbInPlace(mono: FloatArray, room: Double, wet: Double) {
        val st = FloatArray(mono.size * 2) { mono[it / 2] }
        Reverb(room, 0.3, wet).also { it.configure(SR, 2); it.process(st, mono.size, 0) }
        for (i in mono.indices) mono[i] = (st[i * 2] + st[i * 2 + 1]) / 2
    }

    fun normalize(b: FloatArray, peak: Float) {
        val m = b.maxOfOrNull { abs(it) } ?: 0f
        if (m > 0) { val g = peak / m; for (i in b.indices) b[i] *= g }
    }

    // ------------------------------------------------------------------ music

    private fun midi(n: Int) = 440.0 * 2.0.pow((n - 69) / 12.0)

    /** Generates an original stereo music bed. */
    fun music(id: String): Audio {
        val tr = musicList.first { it.id == id }
        val r = java.util.Random(id.hashCode() * 31L)
        val frames = tr.seconds * SR
        val l = FloatArray(frames); val rr = FloatArray(frames)
        val beat = 60.0 / tr.bpm
        val bar = beat * 4
        // chord progressions (root, minor?) in semitones from key
        val key = when (id) { "lofi" -> 57; "pop" -> 60; "ambient" -> 62; "epic" -> 50; "funk" -> 52; else -> 57 }
        val prog = when (id) {
            "lofi" -> listOf(intArrayOf(0, 3, 7, 10), intArrayOf(5, 8, 12, 15), intArrayOf(-2, 2, 5, 9), intArrayOf(3, 7, 10, 14))
            "pop" -> listOf(intArrayOf(0, 4, 7), intArrayOf(7, 11, 14), intArrayOf(9, 12, 16), intArrayOf(5, 9, 12))
            "ambient" -> listOf(intArrayOf(0, 7, 14, 16), intArrayOf(5, 12, 16, 21), intArrayOf(9, 16, 19, 24), intArrayOf(7, 14, 19, 23))
            "epic" -> listOf(intArrayOf(0, 3, 7), intArrayOf(-4, 0, 3), intArrayOf(-7, -3, 0), intArrayOf(-2, 2, 5))
            "funk" -> listOf(intArrayOf(0, 3, 7, 10), intArrayOf(0, 3, 7, 10), intArrayOf(5, 9, 12, 15), intArrayOf(7, 10, 14, 17))
            else -> listOf(intArrayOf(0, 3, 7), intArrayOf(0, 3, 7), intArrayOf(-4, 0, 3), intArrayOf(-2, 2, 5))
        }
        fun add(buf: FloatArray, s: Int, v: Double) { if (s in buf.indices) buf[s] += v.toFloat() }
        val totalBars = (tr.seconds / bar).toInt()
        for (b in 0 until totalBars) {
            val chord = prog[b % prog.size]
            val t0 = b * bar
            val section = when { b < 2 -> 0; b >= totalBars - 2 -> 3; (b / 8) % 2 == 0 -> 1; else -> 2 } // intro, A, B, outro
            // pad / keys
            for ((ni, n) in chord.withIndex()) {
                val f = midi(key + n + (if (id == "epic") 0 else 12))
                val dur = bar
                val s0 = (t0 * SR).toInt(); val len = (dur * SR).toInt()
                for (k in 0 until len) {
                    val t = k.toDouble() / SR
                    val env = min(1.0, t / (if (id == "ambient" || id == "epic") 0.6 else 0.02)) * min(1.0, (dur - t) / 0.3) * (if (id == "lofi" || id == "funk") exp(-t * 1.2) * 0.8 + 0.2 else 1.0)
                    val trem = if (id == "lofi") 0.85 + 0.15 * sin(2 * PI * 5 * t) else 1.0
                    val wave = when (id) {
                        "pop", "tech" -> (2 * ((f * t) % 1.0) - 1) * 0.35 + sin(2 * PI * f * 1.003 * t) * 0.3
                        "epic" -> (2 * ((f * t) % 1.0) - 1) * 0.3 + (2 * ((f * 1.005 * t) % 1.0) - 1) * 0.3
                        else -> sin(2 * PI * f * t) + 0.3 * sin(4 * PI * f * t) * exp(-t * 3)
                    }
                    val v = wave * env * trem * 0.07 * (if (section == 0 || section == 3) 0.7 else 1.0)
                    val pan = (ni - chord.size / 2.0) * 0.25
                    add(l, s0 + k, v * (1 - pan)); add(rr, s0 + k, v * (1 + pan))
                }
            }
            // bass
            if (section != 0 || id == "funk") {
                val root = midi(key + chord[0] - 24)
                val pattern = when (id) { "funk" -> listOf(0.0, 0.75, 1.5, 2.0, 2.5, 3.25); "pop", "tech" -> listOf(0.0, 1.0, 2.0, 3.0); "epic" -> listOf(0.0, 2.0); else -> listOf(0.0, 2.5) }
                for (pb in pattern) {
                    val s0 = ((t0 + pb * beat) * SR).toInt(); val len = (beat * 0.9 * SR).toInt()
                    for (k in 0 until len) { val t = k.toDouble() / SR; val env = min(1.0, t / 0.005) * exp(-t * 3); val v = (sin(2 * PI * root * t) + 0.25 * sin(4 * PI * root * t)) * env * 0.22; add(l, s0 + k, v); add(rr, s0 + k, v) }
                }
            }
            // drums
            if (id != "ambient" && section in 1..2 || (id == "epic" && section != 0)) {
                for (bt in 0 until 4) {
                    val tb = t0 + bt * beat
                    val kick = id == "pop" || id == "tech" || bt % 2 == 0
                    if (kick) drum(l, rr, tb, "kick", r)
                    if (bt % 2 == 1 && id != "epic") drum(l, rr, tb, "snare", r)
                    if (id == "epic" && bt == 2) drum(l, rr, tb, "tom", r)
                    if (id != "epic") { drum(l, rr, tb + beat / 2, "hat", r); if (id == "funk" || id == "tech") { drum(l, rr, tb + beat / 4, "hat", r); drum(l, rr, tb + 3 * beat / 4, "hat", r) } }
                }
            }
            // lo-fi vinyl crackle
            if (id == "lofi") for (k in 0 until (bar * SR).toInt()) if (r.nextDouble() < 0.0006) { val v = noise(r) * 0.15; add(l, (t0 * SR).toInt() + k, v.toDouble()); add(rr, (t0 * SR).toInt() + k, v.toDouble()) }
        }
        // master: interleave, reverb, glue compression, fades, limiter
        val st = FloatArray(frames * 2) { if (it % 2 == 0) l[it / 2] else rr[it / 2] }
        Reverb(if (id == "ambient" || id == "epic") 0.85 else 0.5, 0.4, if (id == "ambient") 0.5 else 0.22).also { it.configure(SR, 2); it.process(st, frames, 0) }
        Compressor(-16.0, 2.5, 15.0, 150.0, 2.0).also { it.configure(SR, 2); it.process(st, frames, 0) }
        val fadeIn = (0.5 * SR).toInt(); val fadeOut = (3.0 * SR).toInt()
        for (f in 0 until frames) {
            val g = min(1.0, f.toDouble() / fadeIn) * min(1.0, (frames - f).toDouble() / fadeOut)
            st[f * 2] = (st[f * 2] * g).toFloat(); st[f * 2 + 1] = (st[f * 2 + 1] * g).toFloat()
        }
        normalize(st, 0.8f)
        Limiter(-1.0).also { it.configure(SR, 2); it.process(st, frames, 0) }
        return Audio(st, 2)
    }

    private fun drum(l: FloatArray, r: FloatArray, timeSec: Double, kind: String, rnd: java.util.Random) {
        val s0 = (timeSec * SR).toInt()
        val len = (when (kind) { "kick" -> 0.35; "snare" -> 0.22; "tom" -> 0.6; else -> 0.06 } * SR).toInt()
        var ph = 0.0
        for (k in 0 until len) {
            val t = k.toDouble() / SR
            val v = when (kind) {
                "kick" -> { ph += 2 * PI * (110 * exp(-t * 25) + 45) / SR; sin(ph) * exp(-t * 9) * 0.55 }
                "snare" -> (noise(rnd) * 0.6 * exp(-t * 22) + sin(2 * PI * 190 * t) * 0.3 * exp(-t * 30)) * 0.35
                "tom" -> { ph += 2 * PI * (90 * exp(-t * 6) + 60) / SR; sin(ph) * exp(-t * 5) * 0.6 }
                else -> noise(rnd) * exp(-t * 90) * 0.12
            }
            val i = s0 + k
            if (i in l.indices) { l[i] += v.toFloat(); r[i] += (v * (if (kind == "hat") 0.7 else 1.0)).toFloat() }
        }
    }
}
